## 1. Fix UGS Game Loading — Fetch HTML directly instead of DOM scraping

**Problem:** The current `loadUGSGames()` approach injects a `<script>` tag loading `games.js` from `genizy/ugs-singlefile@main` into a hidden DOM container, then tries to scrape `<input type="button">` elements. This doesn't work because:
- The UGS `games.js` script uses `document.getElementById('sections-container')` to render buttons, but finding that element in a detached/off-screen div may fail cross-origin or timing issues
- The buttons' onclick contains `location.href=` which tries to navigate the parent page
- A number list 0–10 appears in the sidebar

**Fix:** Replace the DOM scraping approach entirely. Instead, **fetch the raw `games.js` source as text** and parse the game data out of it using regex. The `genizy/ugs-singlefile@main/games.js` file contains calls like:
```
addButton('Game Name', 'https://example.com/game.html')
```
or similar patterns. Fetch the JS as text, then regex-extract all game name+URL pairs.

Here is the correct approach for `loadUGSGames` in `public/gamefetch.js`:

```javascript
export async function loadUGSGames() {
  const cacheKey = 'nebula-zones-ugs-cache';
  const cacheTTL = 30 * 60 * 1000;
  try {
    const cached = sessionStorage.getItem(cacheKey);
    if (cached) {
      const { ts, data } = JSON.parse(cached);
      if (Date.now() - ts < cacheTTL) return data;
    }
  } catch {}

  try {
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 10000);
    const res = await fetch('https://cdn.jsdelivr.net/gh/genizy/ugs-singlefile@main/games.js?t=' + Date.now(), { signal: ctrl.signal });
    clearTimeout(tid);
    const text = await res.text();

    const games = [];
    let i = 0;

    // Pattern 1: addGame('Name', 'url') or addGame("Name", "url")
    const pat1 = /addGame\s*\(\s*['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\s*\)/g;
    let m;
    while ((m = pat1.exec(text)) !== null) {
      games.push({ id: 'ugs_' + i++, name: m[1], url: m[2], cover: null, source: 'ugs' });
    }

    // Pattern 2: addButton('Name', 'url') 
    if (games.length === 0) {
      const pat2 = /addButton\s*\(\s*['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\s*\)/g;
      while ((m = pat2.exec(text)) !== null) {
        games.push({ id: 'ugs_' + i++, name: m[1], url: m[2], cover: null, source: 'ugs' });
      }
    }

    // Pattern 3: value='Name' onclick="location.href='url'" — input button in HTML-in-JS strings
    if (games.length === 0) {
      const pat3 = /value=['"]([^'"]+)['"]\s+onclick=['"](?:location\.href|window\.location)\s*=\s*\\?['"]([^'"\\]+)\\?['"]/g;
      while ((m = pat3.exec(text)) !== null) {
        games.push({ id: 'ugs_' + i++, name: m[1], url: m[2], cover: null, source: 'ugs' });
      }
    }

    // Pattern 4: innerHTML / template literal patterns with location.href
    if (games.length === 0) {
      // Match: <input type="button" value="GAME NAME" onclick="location.href='URL'">
      const pat4 = /value=['"]((?:[^'"\\]|\\.)+)['"]\s+onclick=['"]\s*location\.href\s*=\s*\\?['"]([^'"\\]+)/g;
      while ((m = pat4.exec(text)) !== null) {
        games.push({ id: 'ugs_' + i++, name: m[1].replace(/\\'/g, "'"), url: m[2], cover: null, source: 'ugs' });
      }
    }

    // Pattern 5: Generic — find all pairs of quoted strings where 2nd looks like a URL
    if (games.length === 0) {
      const pat5 = /['"]([A-Za-z0-9 :!@#$%^&*()\-_+=,.?/\\]{3,60})['"]\s*,\s*['"]((https?:\/\/|\/)[^'"]{5,})['"]/g;
      while ((m = pat5.exec(text)) !== null) {
        if (!m[2].includes('.js') && !m[2].includes('.css')) {
          games.push({ id: 'ugs_' + i++, name: m[1], url: m[2], cover: null, source: 'ugs' });
        }
      }
    }

    try { sessionStorage.setItem(cacheKey, JSON.stringify({ ts: Date.now(), data: games })); } catch {}
    return games;
  } catch {
    return [];
  }
}
```

